  // ── Roles ──────────────────────────────────────────────────────────────────
  role_aml_title: { en: 'AML Compliance Officer', vi: 'Chuyên viên Tuân thủ AML' },
  role_aml_briefStd: { en: 'You are the bank\'s money detective. Let honest people through and stop anyone hiding where money really came from.', vi: 'Bạn là thám tử tiền tệ của ngân hàng. Cho người trung thực đi qua và chặn kẻ che giấu nguồn gốc đồng tiền.' },
  role_aml_brief: {
    en: 'Payments the automated screen held as STR_PENDING wait for you. Release genuine customers, block sanctions hits and mule activity.',
    vi: 'Các giao dịch bị sàng lọc tự động giữ lại (STR_PENDING) đang chờ bạn. Giải phóng khách hàng thật, phong tỏa trường hợp trùng cấm vận và tài khoản la (mule).',
  },
  role_aml_reg: { en: 'AML/CTF Act 2006 (Cth) s41 SMR · FATF R.12 (PEPs), R.20 · OFAC SDN', vi: 'Luật AML/CTF 2006 (Úc) mục 41 SMR · FATF R.12 (PEP), R.20 · danh sách OFAC SDN' },
  role_dispute_title: { en: 'Dispute Specialist', vi: 'Chuyên viên Tra soát Khiếu nại' },
  role_dispute_briefStd: { en: 'Customers come to you when a payment went wrong. Check the proof, then decide who gets the money.', vi: 'Khách tìm đến bạn khi một khoản thanh toán gặp sự cố. Xem bằng chứng rồi quyết định ai được nhận tiền.' },
  role_dispute_brief: {
    en: 'Work customer claims within the scheme window. Refund what the evidence supports, reject what the merchant or the journal disproves.',
    vi: 'Xử lý khiếu nại của khách trong thời hạn của tổ chức thẻ. Hoàn tiền khi bằng chứng ủng hộ, từ chối khi người bán hoặc nhật ký máy chứng minh ngược lại.',
  },
  role_dispute_reg: { en: 'Visa Core Rules (reason 13.1) · ISO 20022 pacs.004 · ePayments Code', vi: 'Quy tắc Visa (mã 13.1) · ISO 20022 pacs.004 · Bộ quy tắc ePayments' },
  role_bnpl_title: { en: 'BNPL Credit Officer', vi: 'Chuyên viên Tín dụng BNPL' },
  role_bnpl_briefStd: { en: 'Shoppers ask to pay in four parts. Say yes when they can afford it, no when it would hurt them.', vi: 'Người mua muốn trả làm bốn lần. Đồng ý khi họ trả nổi, từ chối khi điều đó gây hại cho họ.' },
  role_bnpl_brief: {
    en: 'Underwrite Pay-in-4 applications at checkout. Approve affordable plans, decline anyone the policy says cannot carry four instalments.',
    vi: 'Thẩm định hồ sơ trả góp 4 kỳ tại quầy thanh toán. Duyệt các khoản vay vừa khả năng chi trả, từ chối người không đủ điều kiện gánh 4 kỳ.',
  },
  role_bnpl_reg: { en: 'NCCP Act responsible lending · BNPL low-cost credit regime · comprehensive credit reporting', vi: 'Luật NCCP về cho vay có trách nhiệm · khung tín dụng chi phí thấp cho BNPL · báo cáo tín dụng toàn diện' },
  role_cashier_title: { en: 'Branch Cashier', vi: 'Giao dịch viên Quầy tiền mặt' },
  role_cashier_briefStd: { en: 'You look after the cash drawer. Count carefully, refuse fake notes, and never hand out more than you have.', vi: 'Bạn giữ ngăn kéo tiền. Đếm cẩn thận, từ chối tiền giả, và không bao giờ đưa ra nhiều hơn số đang có.' },
  role_cashier_brief: {
    en: 'Count cash in and out against the till. Refuse suspect notes and withdrawals the till cannot cover. Large cash is reported automatically.',
    vi: 'Kiểm đếm tiền nộp và rút theo quỹ quầy. Từ chối tiền nghi giả và lệnh rút vượt quỹ. Giao dịch tiền mặt lớn được báo cáo tự động.',
  },
  role_cashier_reg: { en: 'AML/CTF Act threshold transaction report (TTR/CTR ≥ $10,000) · Crimes (Currency) Act 1981', vi: 'Báo cáo giao dịch vượt ngưỡng theo Luật AML/CTF (TTR/CTR ≥ $10.000) · Luật Tội phạm (Tiền tệ) 1981' },
  role_ekyc_title: { en: 'eKYC Reviewer', vi: 'Chuyên viên Thẩm định eKYC' },
  role_ekyc_briefStd: { en: 'New customers join from their phones. Make sure each one is a real person who matches their ID.', vi: 'Khách mới đăng ký qua điện thoại. Hãy chắc chắn mỗi người là người thật và khớp với giấy tờ.' },
  role_ekyc_brief: {
    en: 'Second-look new accounts the onboarding bot scored. Only real, matching faces with a valid citizen record get an account.',
    vi: 'Rà soát lại các hồ sơ mở tài khoản mà bot đã chấm điểm. Chỉ khuôn mặt thật, khớp giấy tờ và có hồ sơ dân cư hợp lệ mới được mở tài khoản.',
  },
  role_ekyc_reg: { en: 'AML/CTF Rules Part 4 (customer identification) · ISO/IEC 30107-3 PAD · Circular 16/2020 eKYC', vi: 'Quy tắc AML/CTF Phần 4 (định danh khách hàng) · ISO/IEC 30107-3 PAD · Thông tư 16/2020 về eKYC' },
  role_fds_title: { en: 'FDS Fraud Analyst', vi: 'Chuyên viên Phân tích Gian lận FDS' },
  role_fds_briefStd: { en: 'Every phone leaves clues. Add up the warning signs and stop the ones that look like thieves.', vi: 'Mỗi chiếc điện thoại đều để lại dấu vết. Cộng các dấu hiệu cảnh báo và chặn những máy giống kẻ gian.' },
  role_fds_brief: {
    en: 'Score device fingerprints on incoming payments. Block high-risk devices before money moves, let ordinary customers through.',
    vi: 'Chấm điểm dấu vân tay thiết bị của giao dịch. Chặn thiết bị rủi ro cao trước khi tiền đi, cho khách hàng bình thường đi qua.',
  },
  role_fds_reg: { en: 'PCI DSS 4.0 · EMV 3DS risk-based authentication · scheme fraud monitoring programmes', vi: 'PCI DSS 4.0 · xác thực theo rủi ro EMV 3DS · chương trình giám sát gian lận của tổ chức thẻ' },
  role_swift_title: { en: 'Cross-Border Officer', vi: 'Chuyên viên Thanh toán Quốc tế' },
  role_swift_briefStd: { en: 'Money going overseas travels on a strict form. Check every box before it leaves the bank.', vi: 'Tiền đi nước ngoài phải theo một biểu mẫu chặt chẽ. Kiểm tra mọi ô trước khi tiền rời ngân hàng.' },
  role_swift_brief: {
    en: 'Validate outward pacs.008 remittances before they leave the nostro. A malformed message is returned, never sent.',
    vi: 'Kiểm tra điện chuyển tiền đi pacs.008 trước khi rời tài khoản nostro. Điện sai định dạng bị trả lại, không bao giờ được gửi đi.',
  },
  role_swift_reg: { en: 'ISO 20022 pacs.008.001.08 · SWIFT CBPR+ usage guidelines · ISO 9362 BIC · ISO 4217', vi: 'ISO 20022 pacs.008.001.08 · hướng dẫn SWIFT CBPR+ · ISO 9362 BIC · ISO 4217' },



