  scene_task_dispute_2_triggerStd: { en: "The customer was charged for an online order but the merchant did not deliver within the promised time.", vi: "Khách mua hàng online đã bị trừ tiền nhưng Merchant không giao hàng quá SLA." },
  scene_task_dispute_2_triggerExp: { en: "Merchandise-not-received claim past the expected delivery date; issuer must check compelling evidence and merchant pre-arbitration response.", vi: "Khiếu nại không nhận được hàng đã quá hạn giao; ngân hàng phát hành cần kiểm tra bằng chứng và phản hồi của merchant trước trọng tài." },
  task_dispute_3_title: { en: "Stolen card (pacs.004 chargeback)", vi: "Thẻ bị đánh cắp (pacs.004 Chargeback)" },
