  scene_task_dispute_3_triggerStd: { en: "The cardholder reported the card lost and wants the unknown swipes refunded.", vi: "Chủ thẻ báo mất thẻ và yêu cầu đòi bồi hoàn các giao dịch quẹt lạ." },
  scene_task_dispute_3_triggerExp: { en: "Fraud claim: compare the card-status block timestamp with each authorisation timestamp before raising a pacs.004 PaymentReturn.", vi: "Khiếu nại gian lận: so sánh thời điểm khóa thẻ với thời điểm cấp phép từng giao dịch trước khi lập lệnh hoàn trả pacs.004." },
  task_bnpl_1_title: { en: "High debt-to-income (DTI)", vi: "Tỷ lệ nợ DTI cao (>50%)" },
  scene_task_bnpl_1_story: { en: "{name} wants to buy now and pay later for a {amount} purchase.", vi: "{name} muốn mua trước trả sau cho món hàng {amount}." },
  scene_task_bnpl_1_triggerStd: { en: "The customer applied for buy now, pay later, but their monthly repayments take more than 50% of their income.", vi: "Khách đăng ký mua trước trả sau nhưng tổng nghĩa vụ trả nợ hàng tháng chiếm trên 50% thu nhập." },
  scene_task_bnpl_1_triggerExp: { en: "Affordability assessment: debt-to-income ratio from bureau and declared income breaches the responsible-lending cap.", vi: "Đánh giá khả năng chi trả: tỷ lệ nợ trên thu nhập từ dữ liệu tín dụng và thu nhập khai báo vượt trần cho vay có trách nhiệm." },
  task_bnpl_2_title: { en: "Late Pay-in-4 history", vi: "Lịch sử Pay-in-4 trễ hạn" },
