  scene_task_bnpl_2_triggerStd: { en: "The customer had instalment plans paid more than 15 days late in earlier periods.", vi: "Khách có hợp đồng trả góp bị chậm thanh toán hơn 15 ngày ở các kỳ trước." },
  scene_task_bnpl_2_triggerExp: { en: "Internal repayment history shows Pay-in-4 delinquencies above the 15 DPD threshold; limit-increase eligibility check.", vi: "Lịch sử trả nợ nội bộ cho thấy khoản Pay-in-4 quá hạn trên 15 ngày; kiểm tra điều kiện tăng hạn mức." },
  task_bnpl_3_title: { en: "New customer, high limit ($3k)", vi: "Khách mới xin hạn mức cao ($3k)" },
