  scene_task_bnpl_3_triggerExp: { en: "Thin-file applicant: account tenure below the seasoning period, so the new-customer exposure cap applies.", vi: "Khách hàng ít dữ liệu: thời gian mở tài khoản chưa đủ kỳ theo dõi, áp dụng trần hạn mức cho khách mới." },
  task_cashier_1_title: { en: "Large cash ≥ $10k (CTR)", vi: "Giao dịch tiền mặt lớn >= $10k (Báo cáo CTR)" },
