  scene_task_cashier_1_triggerStd: { en: "A customer wants to deposit or withdraw $15,000 in cash at the counter.", vi: "Khách nộp/rút $15,000 tiền mặt hợp lệ tại quầy." },
  scene_task_cashier_1_triggerExp: { en: "Cash transaction at or above the $10,000 threshold: CTR auto-lodged to the regulator once customer identification is verified.", vi: "Giao dịch tiền mặt bằng hoặc vượt ngưỡng $10,000: CTR tự động gửi cơ quan quản lý sau khi xác minh danh tính khách." },
  task_cashier_2_title: { en: "Suspected counterfeit notes", vi: "Nộp tiền mặt nghi giả" },
