  scBreakdown: { en: "{correct} correct · {wrong} errors · +{bonus} speed bonus · −{penalty} penalties", vi: "{correct} đúng · {wrong} lỗi · +{bonus} thưởng tốc độ · −{penalty} bị trừ" },
